// Exact percentile for an EP: percentile of the largest breakpoint <= ep.
export function exactPercentile(ep) {
  if (!(ep >= EP_BREAKS[0])) return 0;
  let lo = 0, hi = EP_BREAKS.length - 1, ans = 0;
  while (lo <= hi) {
    const mid = (lo + hi) >> 1;
    if (EP_BREAKS[mid] <= ep) { ans = PCT_AT[mid]; lo = mid + 1; } else { hi = mid - 1; }
  }
  return ans;
}
